<style>
  .{{judul}}-section {
    max-width: 1200px; /* lebih besar dan landscape */
    margin: 40px auto;
    padding: 50px;
    border-radius: 18px;
    background: #161616;
    border: 2px solid #FFC107 ;
    box-shadow: 0 0 25px #FFC107;
    font-family: "Poppins", sans-serif;
    color: rgb(255, 255, 255);
    position: relative;
    overflow: hidden;
    text-shadow: 0 0 8px rgb(255, 255, 255);
  }

  .{{judul}}-section h2 {
    text-align: center;
    font-size: 32px;
    color: #ffffff;
    text-shadow: 0 0 6px rgb(255, 255, 255);
    margin-bottom: 30px;
    letter-spacing: 1px;
  }

  /* FAQ */
  .{{judul}}-faq {
    max-width: 950px;
    margin: 0 auto 50px;
  }

  .{{judul}}-section details {
    background: #000000;
    border-radius: 12px;
    margin-bottom: 16px;
    padding: 18px 22px;
    border: 1px solid #000000 ;
    transition: 0.3s ease;
  }

  .{{judul}}-section details:hover {
    box-shadow: 0 0 14px #000000;
    transform: translateY(-2px);
  }

  .{{judul}}-section summary {
    cursor: pointer;
    font-size: 18px;
    font-weight: 600;
    color: #ffffff;
    
  }

  .{{judul}}-section details p {
    margin-top: 12px;
    font-size: 16px;
    line-height: 1.7;
  }

 
  .testimoni-wrapper {
    display: grid;
    grid-template-columns: 1fr 1fr; 
    gap: 25px;
    margin-top: 40px;
  }

  .{{judul}}-section blockquote {
    background: #000000;
    border-left: 5px solid #000000 ;
    border-radius: 12px;
    padding: 22px 26px;
    min-height: 160px;
    position: relative;
    box-shadow: 0 0 14px rgba(255 255 255);
    transition: 0.3s;
  }

  .{{judul}}-section blockquote:hover {
    transform: translateY(-4px);
    box-shadow: 0 0 20px rgba(255, 255, 255);
  }

  .{{judul}}-section blockquote::before {
    content: "“";
    font-size: 60px;
    color: rgba(255, 255, 255);
    position: absolute;
    top: 0;
    left: 15px;
    font-family: serif;
  }

  .{{judul}}-section cite {
    display: block;
    margin-top: 18px;
    font-weight: bold;
    color: #ffffff;
    text-align: right;
    text-shadow: 0 0 8px rgb(255, 255, 255);
  }

  /* Footer link */
  .seller-name__detail {
    margin-top: 45px;
    text-align: center;
    grid-column: span 2;
  }

  .seller-name__detail a {
    color: #f8f8f8;
    font-weight: bold;
    font-size: 1.2em;
    text-decoration: none;
    text-shadow: 0 0 8px rgb(255, 255, 255);
  }

  /* Efek shine */
  .{{judul}}-section::before {
    content: "";
    position: absolute;
    top: 0;
    left: -150%;
    width: 50%;
    height: 100%;
    background: linear-gradient(
      120deg,
      rgba(167, 139, 250, 0) 0%,
      rgba(200, 183, 255, 0.33) 50%,
      rgba(167, 139, 250, 0) 100%
    );
    transform: skewX(-20deg);
    animation: shine 3s infinite;
    mix-blend-mode: screen;
    pointer-events: none;
  }

  @keyframes shine {
    0% { left: -150%; }
    100% { left: 150%; }
  }
</style>


